package com.gtalee.covert;
import java.awt.image.BufferedImage; import java.io.*; import java.util.*; import javax.imageio.ImageIO;
public final class FramePatchComposeBuilderTest { public static void main(String[] args) throws Exception { File input=new File(args.length>0?args[0]:"temp_sprite_test_20260925"), out=new File(args.length>1?args[1]:"temp_sprite_test_20260925/frame_patch_output_final"); FramePatchComposeBuilder.Result r=FramePatchComposeBuilder.build(input,out,8,0,1,64); Properties p=new Properties(); FileInputStream in=new FileInputStream(new File(out,"frame_patches.compose.properties")); p.load(in); in.close(); BufferedImage base=ImageIO.read(new File(out,p.getProperty("base"))); int total=0; File[] fs=input.listFiles(new FilenameFilter(){public boolean accept(File d,String n){String x=n.toLowerCase();return x.endsWith(".png")||x.endsWith(".jpg")||x.endsWith(".jpeg");}}); Arrays.sort(fs); for(int fi=0;fi<r.frameCount;fi++){BufferedImage got=new BufferedImage(base.getWidth(),base.getHeight(),BufferedImage.TYPE_INT_ARGB); for(int y=0;y<got.getHeight();y++)for(int x=0;x<got.getWidth();x++)got.setRGB(x,y,base.getRGB(x,y)); String refs=p.getProperty("frame."+fi,""); if(refs.length()>0){String[] a=refs.split(";"); for(int i=0;i<a.length;i++){String[] z=a[i].split("@"); String[] xy=z[1].split(","); BufferedImage patch=ImageIO.read(new File(out,z[0])); int ox=Integer.parseInt(xy[0]),oy=Integer.parseInt(xy[1]); for(int y=0;y<patch.getHeight();y++)for(int x=0;x<patch.getWidth();x++)got.setRGB(ox+x,oy+y,patch.getRGB(x,y));}} BufferedImage expected=ImageIO.read(fs[fi]); for(int y=0;y<got.getHeight();y++)for(int x=0;x<got.getWidth();x++)if(got.getRGB(x,y)!=expected.getRGB(x,y))total++; } if(total!=0)throw new RuntimeException("FAIL diffPixels="+total); System.out.println("PASS reconstruction diffPixels=0 frames="+r.frameCount+" patches="+r.patchCount); }}